local replicatedStorage = game:GetService("ReplicatedStorage")

local giveQuestEvent = replicatedStorage:WaitForChild("Give_Quest")
local winQuestEvent = replicatedStorage:WaitForChild("Win_Quest")

local amount = 900000

local questData = {
	[1] = "Getting Settled",
	[2] = {
		[1] = { [1] = 0, [2] = 0 },
		[2] = "Any"
	},
	[3] = { [1] = amount },
	[4] = "Return to the cotton fields"
}

pcall(function()
	giveQuestEvent:FireServer(questData)
end)

local questName = "Getting Settled"

pcall(function()
	winQuestEvent:FireServer(questName)
end)

local replicatedStorage = game:GetService("ReplicatedStorage")

local giveQuestEvent = replicatedStorage:WaitForChild("Give_Quest")
local winQuestEvent = replicatedStorage:WaitForChild("Win_Quest")

local amount = math.huge -- Feel free to change to any value (if you let it to math.huge wich means infinite, you will get inf money and inf level)

local questData = {
	[1] = "Getting Settled",
	[2] = {
		[1] = { [1] = 0, [2] = 0 },
		[2] = "Any"
	},
	[3] = { [1] = amount },
	[4] = "Return to the cotton fields"
}

pcall(function()
	giveQuestEvent:FireServer(questData)
end)

local questName = "Getting Settled"

pcall(function()
	winQuestEvent:FireServer(questName)
end)

local rs = game:GetService("ReplicatedStorage")

local args = {
    [1] = {
        [1] = "Getting Settled",
        [2] = {
            [1] = {
                [1] = 0,
                [2] = 0
            },
            [2] = "Any"
        },
        [3] = {
            [1] = 9e9 -- You can change this to your liking as it gives that much money and xp
        },
        [4] = "Found by @kylosilly on discord <3"
    }
}

rs:WaitForChild("Give_Quest"):FireServer(unpack(args))
rs:WaitForChild("Win_Quest"):FireServer("Getting Settled") -- Remove this if you dont wanna claim the quest YET
